<section class="page-hero"><div><span class="eyebrow">THE PEOPLE BEHIND THE IDEAS</span><h1><?= e($title) ?></h1><p><?= t('Ranked by completed daily check-ins. Real participation, not purchased popularity.') ?></p></div><span class="page-hero-art"><?= icon('users') ?></span></section><section class="panel glass"><?php $people=$a->db->all("SELECT id,username,display_name,avatar_id,bio,total_checkins,verified FROM cy_users WHERE status='active' ORDER BY total_checkins DESC,id ASC LIMIT 50");foreach ($people as $i=>$person): ?><a class="rank-row" href="<?= e(url('user',['id'=>$person['id']])) ?>"><span class="rank-number"><?= str_pad((string)($i+1),2,'0',STR_PAD_LEFT) ?></span><?= avatar($person) ?><div class="grow"><strong><?= e($person['display_name']) ?><?= $person['verified']?icon('shield'):'' ?></strong><p><?= e($person['bio'] ?: '@'.$person['username']) ?></p></div><span class="rank-score"><?= (int)$person['total_checkins'] ?><small><?= t('Check-ins') ?></small></span></a><?php endforeach ?></section>
